import { TemplateSlide } from 'components';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';

import { StyledContent } from '../../BrandPowerBookExport.styles';
import { PowerBookPerformanceData } from '../../types';
import { ByCountrySlide } from '../ByCountrySlide';

interface GenericPerformanceSlideProps {
  data: PowerBookPerformanceData | undefined | null;
  title: string;
  pageName: string;
  period: string;
  loading: boolean;
  error: Error | null;
  pageIndex?: number;
  footnotes?: JSX.Element | string;
  alerts?: string[];
  isCompetitor?: boolean;
  selectedPeriodType?: string;
}

export const GenericPerformanceSlide = ({
  pageName,
  title,
  period,
  footnotes = '',
  pageIndex,
  loading,
  error,
  data,
  alerts = [],
  isCompetitor = false,
  selectedPeriodType,
}: GenericPerformanceSlideProps) => {
  return (
    <StyledExportPageSection data-page-name={pageName}>
      <TemplateSlide
        enablePngCopy
        title={title}
        period={period}
        footnotes={footnotes}
        page={pageIndex}
        countryId="ABI"
        headerDivider={false}
        dataTestId={pageName}
      >
        <StyledContent>
          <ByCountrySlide
            loading={loading}
            error={error}
            bigNumbersData={data?.bigNumbers}
            zoneKpiData={data?.zonePerformance?.zonePowerPerformance}
            maturityKpiData={
              data?.maturityPerformance?.maturityPowerPerformance
            }
            nazKpiData={data?.zonePerformanceDetails?.NAZ}
            sazKpiData={data?.zonePerformanceDetails?.SAZ}
            mazKpiData={data?.zonePerformanceDetails?.MAZ}
            apacKpiData={data?.zonePerformanceDetails?.APAC}
            afrKpiData={data?.zonePerformanceDetails?.AFR}
            eurKpiData={data?.zonePerformanceDetails?.EUR}
            alerts={alerts}
            isCompetitor={isCompetitor}
            selectedPeriodType={selectedPeriodType}
          />
        </StyledContent>
      </TemplateSlide>
    </StyledExportPageSection>
  );
};
